def gen(rng):
    def fmt(s, groups):
        return f'{len(s)} {len(groups)}\n{s}\n' + '\n'.join(f'{i} {j}' for i, j in groups)
    def rs(m, p):
        return ''.join('1' if rng.random() < p else '0' for _ in range(m))
    def rg(m, k):
        out = []
        for _ in range(k):
            a, b = rng.randint(1, m), rng.randint(1, m)
            out.append((min(a, b), max(a, b)))
        return out
    tests = [fmt('1', [(1, 1)]), fmt('0', [(1, 1)]), fmt('01', [(1, 2)]), fmt('0000', [(1, 4), (2, 3)]),
             fmt('1111', [(1, 4)]), fmt('1001101', [(1, 4), (2, 7), (5, 7)]), fmt('0101', [(2, 2), (1, 3), (3, 4)]),
             fmt('10', [(1, 1), (2, 2)])]
    for m in (3, 5, 8, 12, 20, 30, 50):
        for _ in range(3):
            tests.append(fmt(rs(m, rng.choice([0.2, 0.5, 0.8])), rg(m, rng.randint(1, 6))))
    tests.append(fmt(rs(2000, 0.5), rg(2000, 500)))
    tests.append(fmt(rs(3000, 0.1), rg(3000, 300)))
    M = 200000
    tests.append(fmt(rs(M, 0.5), rg(M, M)))
    tests.append(fmt(rs(M, 0.3), [(1, M)] * 3 + rg(M, M - 3)))
    tests.append(fmt('01' * (M // 2), [(1, M - rng.randint(0, 10)) for _ in range(M)]))
    tests.append(fmt('0' * (M // 2) + '1' * (M // 2), [(rng.randint(1, M // 2), rng.randint(M // 2 + 1, M)) for _ in range(M)]))
    return tests
